import { createHash } from "node:crypto";
import { readdir, readFile, writeFile } from "node:fs/promises";
import { join, relative, resolve } from "node:path";
const root = resolve("dist");
async function walk(dir) {
  const entries = await readdir(dir, { withFileTypes: true });
  return (await Promise.all(entries.map((e) => e.isDirectory() ? walk(join(dir, e.name)) : [join(dir, e.name)]))).flat();
}
const files = (await walk(root)).filter((f) => !f.endsWith(".map") && !f.endsWith("/sw.js") && !f.endsWith("/build-info.json")).sort();
const template = await readFile("scripts/sw-template.js", "utf8");
const hash = createHash("sha256").update(template);
for (const file of files) hash.update(relative(root, file)).update(await readFile(file));
const version = `baseline-${hash.digest("hex").slice(0, 16)}`;
const paths = files.map((file) => "./" + relative(root, file).replaceAll("\\", "/"));
await writeFile(join(root, "sw.js"), template.replace("__SHELL_VERSION__", JSON.stringify(version)).replace("__PRECACHE__", JSON.stringify(paths)));
await writeFile(join(root, "build-info.json"), JSON.stringify({ version, sourceCommit: process.env.SOURCE_COMMIT ?? process.env.GITHUB_SHA ?? "local-unpublished", precacheCount: paths.length }, null, 2));
console.log(`Generated complete offline shell ${version}: ${paths.length} files`);

import { chromium } from "@playwright/test";
import { mkdir, writeFile } from "node:fs/promises";
import assert from "node:assert/strict";
const [url, expected] = process.argv.slice(2);
assert(url && expected, "Provide the Pages URL and expected source SHA");
await mkdir("published-check", {recursive:true});
const browser=await chromium.launch();
const results=[];
try {
  for(const [width,height] of [[1536,691],[896,414]]) {
    const context=await browser.newContext({viewport:{width,height},reducedMotion:"reduce"});
    const page=await context.newPage();const errors=[];page.on("pageerror",e=>errors.push(e.message));
    let info;
    for(let attempt=0;attempt<12;attempt++) {
      const r=await context.request.get(new URL(`build-info.json?verify=${Date.now()}`,url).href);
      if(r.ok()) {info=await r.json();if(info.sourceCommit===expected)break;}
      await new Promise(r=>setTimeout(r,5000));
    }
    assert.equal(info?.sourceCommit,expected,"Published version does not match tested source");
    await page.goto(url,{waitUntil:"networkidle"});
    await page.waitForSelector("#reveal-turn");await page.click("#reveal-turn");
    await page.waitForSelector("#end-turn.end-turn-art-ready:not(:disabled)");
    const geometry=await page.evaluate(()=>{
      const bg=document.querySelector("#battlefield-background img");const button=document.querySelector("#end-turn");
      return {imageDecoded:bg.naturalWidth>0,button:button.getBoundingClientRect().toJSON(),fakeSocket:!!document.querySelector(".stage072b-end-turn-socket")};
    });
    assert(geometry.imageDecoded);assert(!geometry.fakeSocket);assert(geometry.button.width>0);
    await page.screenshot({path:`published-check/${width}x${height}.png`});
    const turn=await page.evaluate(()=>JSON.parse(localStorage.getItem("lushizhizao.basic-game.v1")).state.turn);
    await page.click("#end-turn");await page.waitForSelector("#reveal-turn");
    const after=await page.evaluate(()=>JSON.parse(localStorage.getItem("lushizhizao.basic-game.v1")).state.turn);
    assert.equal(after,turn+1);assert.deepEqual(errors,[]);
    results.push({width,height,info,geometry,turn,after,errors});await context.close();
  }
} finally {await writeFile("published-check/results.json",JSON.stringify(results,null,2));await browser.close();}

// Test-only HTTP server. Mirrors the actual Pages /-/ subpath.
import { createServer } from "node:http";
import { readFile, stat } from "node:fs/promises";
import { resolve, extname, sep } from "node:path";
const root = resolve("dist");
const types = { ".html":"text/html", ".js":"text/javascript", ".css":"text/css", ".json":"application/json", ".webmanifest":"application/manifest+json", ".webp":"image/webp", ".png":"image/png", ".jpg":"image/jpeg", ".svg":"image/svg+xml" };
createServer(async (req,res) => {
  try {
    const url = new URL(req.url, "http://127.0.0.1");
    if (url.pathname === "/") {res.writeHead(302,{Location:"/-/"});res.end();return;}
    if (!url.pathname.startsWith("/-/")) {res.writeHead(404);res.end();return;}
    if (url.pathname === "/-/test-broken-sw.js") {
      const worker=(await readFile(resolve(root,"sw.js"),"utf8"))
        .replace(/const CACHE_NAME = ([^;]+);/, 'const CACHE_NAME = "card-game-shell-test-broken";')
        .replace("const PRECACHE = [", 'const PRECACHE = ["./missing-mandatory-art.webp",');
      res.writeHead(200,{"Content-Type":"text/javascript","Cache-Control":"no-store","Service-Worker-Allowed":"/-/"});res.end(worker);return;
    }
    const name=decodeURIComponent(url.pathname.slice(3)) || "index.html";
    const file=resolve(root,name);
    if (!file.startsWith(root+sep) || !(await stat(file)).isFile()) {res.writeHead(404);res.end();return;}
    res.writeHead(200,{"Content-Type":types[extname(file)]??"application/octet-stream","Cache-Control":"no-store"});res.end(await readFile(file));
  } catch {res.writeHead(404);res.end("Not found");}
}).listen(4174,"127.0.0.1",()=>console.log("Acceptance server: http://127.0.0.1:4174/-/"));
